function localISO(d){const n=new Date(d);return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`;}
function parseISO(s){return new Date(`${s}T12:00:00`);}
function addDays(s,n){const d=parseISO(s);d.setDate(d.getDate()+n);return localISO(d);}
function dateDiff(a,b){return Math.round((parseISO(a)-parseISO(b))/86400000);}
function monday(s){const d=parseISO(s);const diff=(d.getDay()+6)%7;d.setDate(d.getDate()-diff);return localISO(d);}
function weekDays(s){const m=monday(s);return Array.from({length:7},(_,i)=>addDays(m,i));}
function h(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function attr(s){return h(s);}
function titleDate(iso,opts={weekday:'long',month:'long',day:'numeric'}){return parseISO(iso).toLocaleDateString('en-AU',opts);}
function shortDate(iso){return titleDate(iso,{day:'numeric',month:'short'});}
function clamp(n,min,max){return Math.min(max,Math.max(min,n));}
function pct(n,d){return clamp(Math.round((d? n/d:0)*100),0,100);}
