function routineDefaultFor(iso){return (routinePhaseFor(iso).trainingDays||[]).includes(parseISO(iso).getDay())?'training':'regular';}
function routineTypeFor(iso){const override=state.routineOverrides[iso];return override==='regular'||override==='training'?override:routineDefaultFor(iso);}
