function sessionsFor(iso,skill){return state.sessions.filter(s=>s.date===iso&&(!skill||s.skillId===skill));}
function totalMinutes(iso,skill){return sessionsFor(iso,skill).reduce((sum,s)=>sum+Number(s.minutes||0),0);}
function sessionCountWeek(skillId,iso){const week=weekDays(iso);return new Set(state.sessions.filter(s=>s.skillId===skillId&&week.includes(s.date)).map(s=>s.date)).size;}
function habitDone(iso,item){const recorded=!!(dayRecord(iso).habits||{})[item.id]; if(recorded)return true;return !!(item.skillId&&totalMinutes(iso,item.skillId)>=item.minutes);}
function morningProgress(iso){const items=morningItems(iso);return {done:items.filter(i=>habitDone(iso,i)).length,total:items.length};}
function todayActionCount(iso){const d=dayRecord(iso);const habits=d.habits||{};return Object.values(habits).filter(Boolean).length+sessionsFor(iso).length+(d.focusDone?1:0)+(state.dailyReviews[iso]?.mood?1:0);}
function freeDaysFor(iso){return (state.weeks[monday(iso)]?.freeDays||[1,5]).slice();}
function isFree(iso){return freeDaysFor(iso).includes(parseISO(iso).getDay());}
function getGuitarDay(iso){const n=dateDiff(iso,state.settings.sprintStart)+1;return n>=1&&n<=14?n:0;}
function getProject(id){return state.projects.find(p=>p.id===id);}
function firstAction(p){return p?.milestones.find(m=>!m.done)||null;}
function projectPercent(p){return pct(p.milestones.filter(m=>m.done).length,p.milestones.length);}
function selectedFocus(iso){const d=dayRecord(iso);const selected=getProject(d.focusProject);return selected||state.projects.find(p=>p.status==='active'&&firstAction(p))||state.projects[0];}
function btn(text,action,style='button',extra=''){return `<button type="button" class="${style}" data-action="${action}" ${extra}>${text}</button>`;}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastHandle);toastHandle=setTimeout(()=>el.classList.remove('show'),3300);}
