function header(kicker,title,sub,control=''){return `<div class="page-head"><div><div class="overline muted">${kicker}</div><h1>${title}</h1><p>${sub}</p></div>${control?`<div class="page-head-controls">${control}</div>`:''}</div>`;}
function dateButtons(){return `<div class="date-control"><button class="mini-arrow" data-action="prev-day" aria-label="Previous day">‹</button><label class="date-label"><input type="date" id="dateSelect" aria-label="Select date" value="${shownDate}"></label><button class="mini-arrow" data-action="next-day" aria-label="Next day">›</button></div>`;}
function checkedHabitMarkup(item,iso){const done=habitDone(iso,item);return `<label class="habit ${done?'done':''}"><input type="checkbox" data-habit="${attr(item.id)}" ${done?'checked':''} aria-label="Complete ${attr(item.name)}"><span class="habit-glyph">${item.icon}</span><span class="habit-copy"><strong>${h(item.name)}</strong><small>${h(item.meta)}</small></span></label>`;}
