 return `<section class="card daily-edit-compact"><div class="section-title"><div><div class="smallcaps">THE DAILY EDIT / SOFTER CUT</div><h2>Your day, lightly edited</h2></div><span class="chip purple">${EDIT_MODES[edit.mode]?.name||'MAKE'} · ${complete}/${items.length}</span></div><p class="caption">Keep the function, lose the visual overwhelm. Switch the tone of the day, tick things off, and adjust as you go.</p><div class="compact-edit-top"><div class="compact-edit-modes">${Object.entries(EDIT_MODES).map(([k,m])=>`<button class="button small ${edit.mode===k?'':'light'}" data-action="edit-mode" data-mode="${k}">${m.symbol} ${m.name}</button>`).join('')}</div><div class="compact-edit-meta"><span>${mins}m suggested</span><button class="link-btn" data-action="edit-regenerate" data-date="${iso}">New suggestions ↻</button></div></div><div class="compact-edit-list">${items.map(i=>`<div class="compact-plan-item ${i.done?'done':''}"><input type="checkbox" aria-label="Complete ${attr(i.title)}" data-plan-toggle="${attr(i.id)}" data-plan-date="${iso}" ${i.done?'checked':''}><div class="compact-plan-copy"><strong>${h(i.title)}</strong><small>${h(i.kind)} · ${Number(i.duration)||0} min</small></div><div class="compact-plan-actions"><button type="button" class="link-btn" data-action="plan-edit" data-id="${attr(i.id)}" data-date="${iso}">Edit</button></div></div>`).join('')||'<div class="caption">A blank day is allowed. Add whatever belongs here.</div>'}</div><div class="label-split mt-12"><button class="button small" data-action="plan-add" data-date="${iso}">＋ Add a moment</button><button class="link-btn" data-nav="week">Open weekly planner ↗</button></div></section>`;
