 return `<section class="card guitar-panel incantation-panel"><div class="guitar-content"><div class="label-split"><div class="smallcaps">${h(skill.icon)} ${h(skill.name.toUpperCase())} / YOUR CURRENT INCANTATION</div><span class="chip white">Day ${i+1} / 14</span></div><h2>${h(d.title)}</h2><p><b>${h(c.title)}</b> · ${target} minute practice · ${logged} min logged</p><div class="chapter-practice-list">${steps.map((step,n)=>`<label class="chapter-practice-step ${chapterChecked(c,iso,n)?'is-complete':''}"><input type="checkbox" data-chapter-check="${attr(c.id)}" data-check-day="${iso}" data-check-index="${n}" ${chapterChecked(c,iso,n)?'checked':''}><span>${h(step)}</span></label>`).join('')}</div><div class="notice purple" style="margin-bottom:13px"><strong>Today's relic:</strong> ${h(d.goal||'Record one little improvement.')}</div><div class="label-split"><button class="button primary-purple" data-action="log-skill" data-id="${attr(c.skillId)}">＋ Log ${h(skill.name)} practice</button><button class="link-btn" data-nav="skills">${completed}/${steps.length} tasks · chapter details ↗</button></div></div></section>`;
