document.addEventListener('dragstart',e=>{const el=e.target.closest('.edit-item[draggable], .week-plan-item[draggable]');if(!el)return;if(e.target.closest('button, input, label')){e.preventDefault();return;}planDrag={date:el.dataset.planDate,id:el.dataset.planId};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',JSON.stringify(planDrag));el.classList.add('being-dragged');});
