document.addEventListener('drop',e=>{if(!planDrag)return;const zone=e.target.closest('[data-drop-date]');if(!zone)return;e.preventDefault();const src=planDrag.date,id=planDrag.id,tgt=zone.dataset.dropDate;const hover=e.target.closest('.edit-item[data-plan-id],.week-plan-item[data-plan-id]');let idx=null;if(hover&&hover.dataset.planId!==id){const arr=dailyEdit(tgt).items;idx=arr.findIndex(i=>i.id===hover.dataset.planId);if(idx>=0){const rect=hover.getBoundingClientRect();if(e.clientY>rect.top+rect.height/2)idx++;}}moveItem(src,tgt,id,idx);dailyEdit(src).edited=true;dailyEdit(tgt).edited=true;save();planDrag=null;toast(src===tgt?'Rearranged your edit.':'Moved to '+shortDate(tgt)+'.');});
