/* OPEN/DAYS 10 · AFTERHOURS ARCHIVE
   All new data lives alongside, never instead of, the previous nine issues. */
function ensureV10(){
 state.weeklyIssues ||= {};
 state.archiveDrafts ||= {};
 state.weeklyResets ||= {};
 for(const s of Object.values(state.projectSpaces||{}))if(s && typeof s==='object')s.toolkits ||= {};
}
let archiveWeek=monday(shownDate);
function datesOf(week){return weekDays(week);}
function weekDigest(week){
 const dates=datesOf(week),end=dates[6],sessions=state.sessions.filter(s=>dates.includes(s.date));
 const minutes=sessions.reduce((sum,s)=>sum+(+s.minutes||0),0), practiceDays=new Set(sessions.map(s=>s.date)).size;
 const moments=dates.map(date=>({date,...(state.dailyReviews?.[date]||{})})).filter(x=>x.moment||x.learning);
 const events=state.events.filter(e=>e.date<=end && (e.endDate||e.date)>=week).map(e=>({title:e.title,date:e.date,icon:e.icon||'◷'}));
 const journal=[];for(const p of state.projects)for(const u of (state.projectSpaces?.[p.id]?.updates||[]))if(dates.includes(u.date))journal.push({project:p.name,text:u.text,date:u.date});
 const focusDays=dates.filter(d=>state.days[d]?.focusDone).length;
 const plans=dates.flatMap(d=>(state.dailyEdits?.[d]?.items||[]).filter(i=>i.done).map(i=>({date:d,title:i.title})));
 const featured=[...new Set([...journal.map(u=>u.project),...dates.map(d=>state.days?.[d]?.focusDone?getProject(state.days[d].focusProject)?.name:null).filter(Boolean)])].slice(0,4);
 const highlightSkills=Object.entries(sessions.reduce((map,s)=>{map[s.skillId]=(map[s.skillId]||0)+(+s.minutes||0);return map;},{})).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([id,mins])=>({name:state.skills.find(s=>s.id===id)?.name||'Archived skill',mins}));
 return {minutes,practiceDays,focusDays,plans:plans.length,moments,events,journal,featured,highlightSkills};
}
function archiveDraft(week){ensureV10();return state.archiveDrafts[week] ||= {title:'The days in between.',subtitle:'Collecting the little things',story:'',layout:'spread',cover:''};}
function issueFor(week){ensureV10();return state.weeklyIssues[week]||null;}
function archiveTitleSuggestion(week){const digest=weekDigest(week);return digest.events.length?'Somewhere between here & there.':digest.practiceDays>3?'A little more becoming.':'The days in between.';}
function displayWeekLabel(week){return `${shortDate(week)} — ${shortDate(addDays(week,6))} ${parseISO(week).getFullYear()}`;}
function archivePhotoMarkup(src){if(!src)return '<div class="archive-no-photo"><span>✿</span><i>a little world of your own</i><small>ADD A PHOTO OR KEEP THE ABSTRACT COVER</small></div>';
 if(!/^https?:\/\//i.test(src)&&!/^data:image\/(?:jpeg|png|webp);base64,/i.test(src))return archivePhotoMarkup('');
 return `<img loading="lazy" src="${attr(src)}" alt="Your chosen weekly cover photograph">`;
}
function archiveSpread(week,issue,draftMode=false){const stats=issue?.stats||weekDigest(week),layout=['spread','poster','notes'].includes(issue?.layout)?issue.layout:'spread';
 const title=issue?.title||archiveTitleSuggestion(week),subtitle=issue?.subtitle||'A life in progress.',story=issue?.story||'';
 const scenes=stats.moments||[],events=stats.events||[],skills=stats.highlightSkills||[];
 return `<article class="archive-spread layout-${layout}">
   <section class="archive-spread-art"><div class="archive-image-frame">${archivePhotoMarkup(issue?.cover||'')}</div><div class="archive-photo-overlay"><small>OPEN/DAYS • ISSUE ${String(Math.max(1,Math.round(dateDiff(week,'2026-11-02')/7)+1)).padStart(3,'0')}</small><b>the little<br><em>things.</em></b></div><div class="archive-scribble">days worth<br>remembering <span>↗</span></div></section>
   <section class="archive-spread-copy"><div class="archive-kicker"><span>THE LIFE ARCHIVE</span><span>${h(displayWeekLabel(week))}</span></div><h2>${h(title)}</h2><p class="archive-dek">${h(subtitle)}</p><div class="archive-number-strip"><div><strong>${Math.round(stats.minutes/60*10)/10}<small>h</small></strong><span>skill practice</span></div><div><strong>${stats.practiceDays}</strong><span>days practised</span></div><div><strong>${stats.events.length}</strong><span>events & adventures</span></div></div><div class="archive-body-copy">${story?h(story):'A page for what mattered. Add a story, a memory, or a moment that made the week feel like yours.'}</div><div class="archive-clip-row">${scenes.slice(0,2).map(m=>`<div class="archive-clip"><small>${shortDate(m.date)}</small><p>${h(m.moment||m.learning)}</p></div>`).join('')||'<div class="archive-clip"><small>FIELD NOTE 01</small><p>Your first memory can live right here.</p></div>'}</div></section>
   <section class="archive-bottom-ribbon"><span>${skills.length?skills.map(s=>`${h(s.name)} / ${s.mins}m`).join(' ✳ '):'NO PRACTICE LOGS REQUIRED TO HAVE A GOOD WEEK'}</span><span>${events.length?events.slice(0,2).map(e=>h(e.title)).join(' · '):'AN OPEN HORIZON'}</span></section>
  </article>`;
}
