function guessedToolKind(p){const text=(p.name+' '+p.category).toLowerCase();return /film|video|shoot|storyboard/.test(text)?'film':/writing|substack|blog|essay|publish/.test(text)?'writing':/bolo|bread|baking|recipe|pastry|cafe|café/.test(text)?'recipe':/grant|appl|adventure|opportunit|residency/.test(text)?'application':/design|fusion|ceramic|prototype|woodwork|portfolio/.test(text)?'design':'general';}
function toolkitFor(p){const s=projectSpace(p.id);s.toolkits||={};s.toolkits.active||=guessedToolKind(p);s.toolkits.boards||={};return s.toolkits;}
function renderStudioToolbox(){const p=getProject(selectedStudioId)||state.projects[0];if(!p)return '';const kit=toolkitFor(p),kind=TOOL_KINDS[kit.active]?kit.active:'general',spec=TOOL_KINDS[kind],rows=kit.boards[kind]||[];
 return `<section class="card project-tool-module"><div class="tool-module-top"><div><span class="smallcaps">05 / YOUR SPECIALIST DESK</span><h2>Make it <em>real.</em></h2><p>${h(spec.intro)} Switch between desks anytime; each keeps its own entries.</p></div><div class="tool-module-picker"><label for="studioToolKind">YOUR PROJECT TOOL</label><select id="studioToolKind" data-tool-kind="${attr(p.id)}">${Object.entries(TOOL_KINDS).map(([k,v])=>`<option value="${k}" ${kind===k?'selected':''}>${h(v.name)}</option>`).join('')}</select></div></div><div class="tool-module-toolbar"><span>${rows.length} items · ${h(spec.name)}</span><button class="button" data-action="tool-row-add" data-id="${attr(p.id)}">＋ Add an entry</button></div><div class="tool-module-list">${rows.map((r,i)=>`<article class="tool-module-row"><span class="tool-row-index">${String(i+1).padStart(2,'0')}</span><div class="tool-row-copy"><strong>${h(r.name)}</strong><span>${h(r.detail||'')}</span><small>${h(r.place||'')}</small></div><div class="tool-row-end"><span class="tool-row-status">${h(r.status||'Idea')}</span><button class="link-btn" data-action="tool-row-edit" data-id="${attr(p.id)}" data-row="${attr(r.id)}">Edit</button><button class="link-btn" data-action="tool-row-delete" data-id="${attr(p.id)}" data-row="${attr(r.id)}" aria-label="Remove ${attr(r.name)}">×</button></div></article>`).join('')||'<div class="tool-empty">Your workbench is clear. Add a shot, an essay, an experiment or an application to start making progress.</div>'}</div><div class="tool-module-foot">These tools are optional. Your existing milestones, references, studio diary and notes are unchanged.</div></section>`;
}
function toolRowModal(pid,rowId=''){const p=getProject(pid);if(!p)return;const kit=toolkitFor(p),kind=kit.active,spec=TOOL_KINDS[kind],row=(kit.boards[kind]||[]).find(r=>r.id===rowId)||{};
 const fields=spec.fields.map(f=>`<div class="field"><label>${h(f.label)}</label>${f.type==='select'?`<select name="${f.key}">${f.options.map(o=>`<option value="${attr(o)}" ${row[f.key]===o?'selected':''}>${h(o)}</option>`).join('')}</select>`:`<input name="${f.key}" type="${f.type||'text'}" maxlength="${f.type==='url'?900:400}" value="${attr(row[f.key]||'')}" ${f.required?'required':''}>`}</div>`).join('');
 modal({title:rowId?'Edit your creative work':'Add to '+spec.name,content:`<form id="toolRowForm" class="modal-form"><input type="hidden" name="pid" value="${attr(pid)}"><input type="hidden" name="kind" value="${attr(kind)}"><input type="hidden" name="row" value="${attr(rowId)}">${fields}<div class="modal-actions"><button type="button" class="button light" data-action="close-modal">Cancel</button><button type="submit" class="button">Save this entry ↗</button></div></form>`});
}
function renderWeek10(){return renderWeekCore()+`<section class="weekly-reset-shortcut"><div><span class="smallcaps">BONUS SPREAD / THE WEEKLY RESET</span><h2>Before the week turns <em>another page.</em></h2><p>Reflect on what mattered, then gently curate what deserves your next week.</p></div><button class="button" data-nav="reset">↗ Open Weekly Reset</button></section>`;}
function renderStudio10(){return renderStudioCore()+renderStudioToolbox();}
function renderReflect10(){return renderReflectCore()+`<div class="archive-reflect-link"><span>YOUR NOTES CAN BECOME A MAGAZINE SPREAD</span><button class="button light" data-nav="archive">✳ Visit the Life Archive ↗</button></div>`;}

// All V10 actions are additive. They do not intercept or rewrite V9 data handlers.
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action==='archive-prev'||action==='archive-next'){archivedFormDraft(archiveWeek);archiveWeek=addDays(archiveWeek,action==='archive-prev'?-7:7);goto('archive');}
 if(action==='archive-open'){archivedFormDraft(archiveWeek);archiveWeek=b.dataset.week;goto('archive');}
 if(action==='archive-clear-cover'){archivedFormDraft(archiveWeek);const draft=archiveDraft(archiveWeek);draft.cover='';draft.clearCover=true;save();render();toast('Cover cleared in this issue draft. Save to confirm.');}
 if(action==='archive-delete'){if(!confirm('Remove this saved magazine issue? Your underlying practice logs and notes will remain.'))return;delete state.weeklyIssues[b.dataset.week];save();render();toast('Issue removed; original memories kept.');}
 if(action==='reset-prev'||action==='reset-next'){shownDate=addDays(shownDate,action==='reset-prev'?-7:7);goto('reset');}
 if(action==='reset-to-archive'){archiveWeek=b.dataset.week||monday(shownDate);goto('archive');}
 if(action==='reset-apply'){
   const week=monday(shownDate);if(!weeklyResetRecord(week)){toast('Save your reflection first.');return;}
   const candidates=suggestedNextWeek(week),selected=candidates.filter((p,i)=>document.querySelector(`[data-reset-pick="${i}"]`)?.checked);
   if(!selected.length){toast('Select at least one suggestion.');return;}
   let count=0;for(const p of selected){if(isFree(p.date)||isTravel(p.date)||state.events.some(e=>e.date<=p.date&&(e.endDate||e.date)>=p.date))continue;
     const edit=dailyEdit(p.date);if(edit.items.some(i=>i.title===p.title))continue;
     edit.items.push({id:uniqueId('plan'),title:p.title,kind:p.kind,duration:p.duration,refId:p.refId,done:false,fromReset:true});edit.edited=true;count++;}
   state.weeklyResets[week].appliedAt=new Date().toISOString();save();render();toast(count?`Added ${count} plan${count===1?'':'s'} without changing your other cards.`:'Everything selected was already planned.');
 }
 if(action==='tool-row-add'||action==='tool-row-edit')toolRowModal(b.dataset.id,action==='tool-row-edit'?b.dataset.row:'');
 if(action==='tool-row-delete'){const p=getProject(b.dataset.id);if(!p||!confirm('Remove this workspace entry?'))return;const kit=toolkitFor(p);kit.boards[kit.active]=(kit.boards[kit.active]||[]).filter(r=>r.id!==b.dataset.row);save();render();toast('Entry removed.');}
});
document.addEventListener('change',e=>{
 const select=e.target.closest('[data-tool-kind]');if(select){const p=getProject(select.dataset.toolKind);if(p&&TOOL_KINDS[select.value]){toolkitFor(p).active=select.value;save();render();}return;}
 if(e.target.id==='archiveFile'&&e.target.files?.[0]){
   const file=e.target.files[0];if(!/^image\/(?:jpeg|png|webp)$/.test(file.type)||file.size>8000000){toast('Choose a JPG, PNG or WebP image smaller than 8 MB.');return;}
   const reader=new FileReader();reader.onload=()=>{const im=new Image();im.onload=()=>{try{
      archivedFormDraft(archiveWeek);const max=920,scale=Math.min(1,max/Math.max(im.width,im.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.width*scale));canvas.height=Math.max(1,Math.round(im.height*scale));canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.68);
      if(data.length>300000){toast('This photo is too detailed for local storage. Try a smaller image.');return;}
      archiveDraft(archiveWeek).cover=data;archiveDraft(archiveWeek).clearCover=false;archiveDraft(archiveWeek).edited=true;const url=document.getElementById('archiveUrl');if(url)url.value='';save();render();toast('Photo added to this issue draft. Publish to freeze it.');
   }catch(ex){toast('Could not prepare that photo.');}};im.onerror=()=>toast('Could not open the image.');im.src=reader.result;};reader.onerror=()=>toast('Could not read that image.');reader.readAsDataURL(file);
 }
});
document.addEventListener('submit',e=>{
 const id=e.target.id;if(!['archiveForm','weeklyResetForm','toolRowForm'].includes(id))return;e.preventDefault();const f=new FormData(e.target);ensureV10();
 if(id==='archiveForm'){
  const week=String(f.get('week')||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(week))return;
  const title=String(f.get('title')||'').trim().slice(0,110),subtitle=String(f.get('subtitle')||'').trim().slice(0,160),story=String(f.get('story')||'').trim().slice(0,3500);
  const layout=['spread','poster','notes'].includes(f.get('layout'))?String(f.get('layout')):'spread',raw=String(f.get('coverUrl')||'').trim().slice(0,1500);
  if(!title){toast('Give your issue a headline.');return;}if(raw&&!/^https?:\/\//i.test(raw)){toast('Use a complete image URL.');return;}
  const old=issueFor(week),draft=archiveDraft(week),cover=draft.clearCover?'':(raw||draft.cover||old?.cover||'');
  state.weeklyIssues[week]={title,subtitle,story,layout,cover,stats:weekDigest(week),savedAt:new Date().toISOString()};
  delete state.archiveDrafts[week];save();render();toast('Your weekly issue is published ✳');return;
 }
 if(id==='weeklyResetForm'){
  const week=String(f.get('week')||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(week))return;
  const old=state.weeklyResets[week]||{};state.weeklyResets[week]={...old,bright:String(f.get('bright')||'').slice(0,1600),drained:String(f.get('drained')||'').slice(0,1600),more:String(f.get('more')||'').slice(0,1600),intention:String(f.get('intention')||'').slice(0,180),pace:['light','balanced','ambitious'].includes(f.get('pace'))?String(f.get('pace')):'balanced',projectId:state.projects.some(p=>p.id===f.get('projectId'))?String(f.get('projectId')):'',skillId:state.skills.some(s=>s.id===f.get('skillId'))?String(f.get('skillId')):'',savedAt:new Date().toISOString()};
  save();render();toast('Your reset is saved. Preview your optional next-week plans.');return;
 }
 if(id==='toolRowForm'){
  const pid=String(f.get('pid')||''),p=getProject(pid),kind=String(f.get('kind')||'');if(!p||!TOOL_KINDS[kind])return;
  const name=String(f.get('name')||'').trim().slice(0,400);if(!name){toast('Give the entry a name.');return;}
  const urlField=TOOL_KINDS[kind].fields.find(x=>x.type==='url'),url=urlField?String(f.get(urlField.key)||'').trim():'';if(url&&!/^https?:\/\//i.test(url)){toast('Please enter a valid http(s) link.');return;}
  const kit=toolkitFor(p);kit.boards[kind]||=[];
  const row=kit.boards[kind].find(r=>r.id===f.get('row'))||{id:uniqueId('tool')};for(const field of TOOL_KINDS[kind].fields)row[field.key]=String(f.get(field.key)||'').trim().slice(0,field.type==='url'?900:400);
  if(!kit.boards[kind].some(r=>r.id===row.id))kit.boards[kind].push(row);
  save();closeModal();render();toast('Added to your creative workspace.');return;
 }
});

