function ensureMastery(){
 if(!state.masteryTrees||typeof state.masteryTrees!=='object'||Array.isArray(state.masteryTrees))state.masteryTrees={};
 if(!state.masteryProofs||typeof state.masteryProofs!=='object'||Array.isArray(state.masteryProofs))state.masteryProofs={};
}
function seedMasteryTree(skill){
 const names=MASTERY_BLUEPRINTS[skill.id]||[
  ['First encounter',`Learn and demonstrate one essential foundation of ${skill.name}.`],
  ['The repeatable ritual',`Repeat a foundational ${skill.name} task with increasing consistency.`],
  ['Technique spark',`Demonstrate a technical skill used in ${skill.name}.`],
  ['Reliable execution',`Perform the skill consistently and record the result.`],
  ['Find your style',`Experiment with a new creative or personal approach to ${skill.name}.`],
  ['Make it yours',`Create or demonstrate an original application of ${skill.name}.`],
  ['The combined test',`Combine technique and personal expression in one complete challenge.`],
  ['The first ascension',`Produce evidence of your progress in ${skill.name} and reflect on improvements.`]
 ];
 return MASTERY_SCHEMA.map(([key,branch,glyph,requires],i)=>({id:`seed-${skill.id}-${key}`,branch,glyph,title:names[i][0],challenge:names[i][1],requires:requires.map(k=>`seed-${skill.id}-${k}`)}));
}
function masteryData(skillId){
 ensureMastery();
 const skill=state.skills.find(s=>s.id===skillId);
 if(!skill)return {nodes:[],proofs:{}};
 const tree=state.masteryTrees[skillId];
 if(!Array.isArray(tree)){state.masteryTrees[skillId]=seedMasteryTree(skill);save();}
 if(!state.masteryProofs[skillId]||typeof state.masteryProofs[skillId]!=='object')state.masteryProofs[skillId]={};
 return {nodes:state.masteryTrees[skillId],proofs:state.masteryProofs[skillId]};
}
function masteryStatus(node,proofs){if(proofs[node.id])return 'claimed';return (node.requires||[]).every(id=>!!proofs[id])?'ready':'locked';}
function masteryProgress(skillId){const {nodes,proofs}=masteryData(skillId);return {total:nodes.length,claimed:nodes.filter(n=>!!proofs[n.id]).length,available:nodes.filter(n=>masteryStatus(n,proofs)==='ready').length};}
function masteryBadgeSymbol(s){return s==='claimed'?'✶':s==='ready'?'✧':'♢';}
function renderMasteryAtlas(){
 const skill=state.skills.find(s=>s.id===selectedStarId)||state.skills[0];if(!skill)return '';
 const {nodes,proofs}=masteryData(skill.id),progress=masteryProgress(skill.id);
 const lanes=MASTERY_LANES.map(lane=>`<div class="mastery-lane" data-mastery-lane="${lane.key}"><div class="mastery-lane-heading"><span class="mastery-lane-glyph">${lane.glyph}</span><div><span>${lane.name}</span><small>${lane.subtitle}</small></div></div><div class="mastery-lane-stack">${nodes.filter(n=>n.branch===lane.key).map(node=>{
 const status=masteryStatus(node,proofs),p=proofs[node.id];
 return `<button type="button" data-action="mastery-open" data-id="${attr(node.id)}" class="mastery-node ${status}" data-mastery-cell="${attr(node.id)}" aria-label="${attr(node.title)}. ${status==='claimed'?'Achieved':status==='ready'?'Ready to attempt':'Locked'}"><span class="mastery-node-top"><span class="mastery-node-glyph">${h(node.glyph||'✧')}</span><span class="mastery-node-state">${status==='claimed'?'✦ EARNED':status==='ready'?'◌ AVAILABLE':'◇ SEALED'}</span></span><strong>${h(node.title)}</strong><span class="mastery-node-desc">${h(node.challenge)}</span><span class="mastery-node-foot">${status==='claimed'?`SEALED ON ${h(shortDate(p.completedAt||localISO(new Date())))}`:status==='ready'?'OPEN CHALLENGE ↗':`${(node.requires||[]).length} PREREQUISITE${(node.requires||[]).length===1?'':'S'}`}</span></button>`;
 }).join('')||`<div class="mastery-empty-lane">No sigils here.<br>Add one to shape your path.</div>`}</div></div>`).join('');
 return `<section id="masteryAtlas" class="mastery-shell"><div class="mastery-heading"><div><span class="mastery-kicker">✦ ALCHEMY DEPARTMENT / SKILL MASTERY</span><h2>The <em>Mastery Grimoire.</em></h2><p>XP measures time invested. These sigils mark abilities you actually demonstrated. No streaks, no lost progress, and no instant mastery from minutes alone.</p></div><div class="mastery-stamp"><span>THE PATH OF</span><strong>${h(skill.name)}</strong><small>YOUR OWN MAGIC / NO. 011</small></div></div>
 <div class="mastery-ribbon"><div class="mastery-filter"><label for="masterySkillPicker">CURRENT PATH</label><select id="masterySkillPicker">${state.skills.map(s=>`<option value="${attr(s.id)}" ${s.id===skill.id?'selected':''}>${h(s.icon)} ${h(s.name)}</option>`).join('')}</select></div><div class="mastery-metric"><strong>${progress.claimed}<small> / ${progress.total}</small></strong><span>sigils recovered</span></div><div class="mastery-metric"><strong>${progress.available}</strong><span>ready to attempt</span></div><button class="button mastery-add" type="button" data-action="mastery-add">＋ Design a sigil</button></div>
 <div class="mastery-progress"><div style="width:${pct(progress.claimed,progress.total)}%"></div></div>
 <div class="mastery-scroll" tabindex="0" aria-label="Scrollable mastery skill tree, four pathways"><div class="mastery-board" id="masteryBoard"><svg id="masteryThreads" class="mastery-threads" aria-hidden="true"></svg><div class="mastery-grid">${lanes}</div><div class="mastery-board-foot"><span>✳ COMPLETE THE PROOF · BRANCH INTO YOUR OWN SKILLS</span><span>NO SHORTCUTS / ONLY DISCOVERY</span></div></div></div>
 <div class="mastery-bottom"><span>◌ Scroll sideways on a phone to explore the pathways. Connectors show prerequisites.</span><div><button class="link-btn" type="button" data-action="mastery-reset">↺ Restore starter path</button><button class="link-btn" type="button" data-action="mastery-guide">How do sigils work? ↗</button></div></div></section>`;
}
function drawMasteryPaths(){
 const board=document.getElementById('masteryBoard'),svg=document.getElementById('masteryThreads');if(!board||!svg)return;
 const skill=state.skills.find(s=>s.id===selectedStarId)||state.skills[0];if(!skill)return;
 const {nodes,proofs}=masteryData(skill.id),rect=board.getBoundingClientRect();
 const w=board.offsetWidth,hgt=board.offsetHeight;svg.setAttribute('viewBox',`0 0 ${w} ${hgt}`);svg.replaceChildren();
 const lookup=new Map([...board.querySelectorAll('[data-mastery-cell]')].map(el=>[el.dataset.masteryCell,el]));
 for(const node of nodes){const dest=lookup.get(node.id);if(!dest)continue;
 for(const id of node.requires||[]){const source=lookup.get(id);if(!source)continue;
 const a=source.getBoundingClientRect(),b=dest.getBoundingClientRect();
 const x1=a.right-rect.left-3,y1=a.top-rect.top+a.height/2,x2=b.left-rect.left+3,y2=b.top-rect.top+b.height/2;
 const curve=Math.max(46,Math.abs(x2-x1)*.48);
 const path=document.createElementNS('http://www.w3.org/2000/svg','path');
 path.setAttribute('d',`M ${x1} ${y1} C ${x1+curve} ${y1}, ${x2-curve} ${y2}, ${x2} ${y2}`);
 path.setAttribute('class',proofs[id]&&proofs[node.id]?'mastery-line earned':proofs[id]?'mastery-line available':'mastery-line dormant');
 svg.appendChild(path);
 }
 }
}
function masteryNodeById(skillId,nodeId){return masteryData(skillId).nodes.find(n=>n.id===nodeId);}
function masteryNodeModal(nodeId){
 const skill=state.skills.find(s=>s.id===selectedStarId)||state.skills[0];if(!skill)return;
 const {nodes,proofs}=masteryData(skill.id),node=nodes.find(n=>n.id===nodeId);if(!node)return;
 const status=masteryStatus(node,proofs),proof=proofs[node.id],requires=(node.requires||[]).map(id=>nodes.find(n=>n.id===id)).filter(Boolean);
 modal({title:`${h(node.glyph||'✧')} ${h(node.title)}`,content:`<div class="mastery-detail"><span class="mastery-detail-state ${status}">${status==='claimed'?'✦ ACHIEVED':status==='ready'?'✧ READY TO ATTEMPT':'◇ NOT YET UNLOCKED'}</span><p class="mastery-detail-challenge">${h(node.challenge)}</p><div class="mastery-detail-parents"><span class="smallcaps">REQUIRED FIRST</span>${requires.length?requires.map(n=>`<div class="mastery-parent ${proofs[n.id]?'complete':''}">${proofs[n.id]?'✦':'◇'} ${h(n.title)}</div>`).join(''):'<p>None — this is a starting point.</p>'}</div>${proof?`<div class="mastery-proof-display"><span class="smallcaps">PROOF OF BECOMING / ${h(proof.completedAt||'')}</span><p>${h(proof.note||'')}</p>${proof.link?`<a href="${attr(proof.link)}" target="_blank" rel="noopener noreferrer">View your evidence ↗</a>`:''}</div>`:''}<div class="modal-actions"><button type="button" class="button light" data-action="mastery-edit" data-id="${attr(node.id)}">✎ Edit challenge</button>${proof?`<button class="button ghost" type="button" data-action="mastery-undo" data-id="${attr(node.id)}">Undo sigil</button><button class="button" type="button" data-action="mastery-proof" data-id="${attr(node.id)}">Update proof ↗</button>`:status==='ready'?`<button class="button" type="button" data-action="mastery-proof" data-id="${attr(node.id)}">✦ Claim with proof</button>`:'<button class="button light" type="button" data-action="close-modal">Continue practising</button>'}</div></div>`});
}
function masteryProofModal(nodeId){
 const skill=state.skills.find(s=>s.id===selectedStarId)||state.skills[0];if(!skill)return;
 const {nodes,proofs}=masteryData(skill.id),node=nodes.find(n=>n.id===nodeId);if(!node)return;
 if(masteryStatus(node,proofs)==='locked'){toast('Complete its prerequisites before claiming this sigil.');return;}
 const existing=proofs[nodeId];modal({title:existing?'Edit your proof':'Claim a new sigil',content:`<form class="modal-form" id="masteryProofForm"><input type="hidden" name="skillId" value="${attr(skill.id)}"><input type="hidden" name="nodeId" value="${attr(nodeId)}"><p><strong>${h(node.title)}</strong> — ${h(node.challenge)}</p><div class="field"><label>What did you actually demonstrate?</label><textarea required name="note" maxlength="1600" rows="5" minlength="10" placeholder="I recorded a full minute at 70 BPM without stopping…">${h(existing?.note||'')}</textarea></div><div class="field"><label>Optional evidence link (recording, portfolio, note)</label><input name="link" type="url" maxlength="1200" value="${attr(existing?.link||'')}" placeholder="https://..."></div><div class="modal-actions"><button type="button" class="button light" data-action="close-modal">Cancel</button><button type="submit" class="button">✦ ${existing?'Update':'Claim'} sigil</button></div><p class="caption">You verify your own progress. This does not add practice minutes or XP. Log those separately.</p></form>`});
}
function masteryNodeEditModal(nodeId=''){
 const skill=state.skills.find(s=>s.id===selectedStarId)||state.skills[0];if(!skill)return;
 const {nodes}=masteryData(skill.id),node=nodes.find(n=>n.id===nodeId),id=node?.id||'';
 modal({title:id?'Edit your sigil':'Design a new sigil',content:`<form class="modal-form mastery-node-form" id="masteryNodeForm"><input type="hidden" name="skillId" value="${attr(skill.id)}"><input type="hidden" name="id" value="${attr(id)}"><div class="field"><label>Sigil name</label><input name="title" required maxlength="90" value="${attr(node?.title||'')}" placeholder="The deep blue hour"></div><div class="field"><label>Demonstrable challenge / finish line</label><textarea required name="challenge" maxlength="650" rows="4" placeholder="Record, demonstrate, build, perform, publish…">${h(node?.challenge||'')}</textarea></div><div class="inline-fields"><div class="field"><label>Path</label><select name="branch">${MASTERY_LANES.map(l=>`<option value="${l.key}" ${node?.branch===l.key?'selected':''}>${l.name}</option>`).join('')}</select></div><div class="field"><label>Symbol</label><input name="glyph" maxlength="3" value="${attr(node?.glyph||'✧')}"></div></div><div class="field"><label>Prerequisites / unlock once these are earned</label><div class="mastery-prereqs">${nodes.filter(n=>n.id!==id).map(n=>`<label><input type="checkbox" name="requires" value="${attr(n.id)}" ${(node?.requires||[]).includes(n.id)?'checked':''}><span>${h(n.glyph||'✧')} ${h(n.title)}</span></label>`).join('')||'<p>No other sigils yet.</p>'}</div></div><div class="modal-actions">${id?`<button type="button" class="button ghost" data-action="mastery-delete" data-id="${attr(id)}">Delete sigil</button>`:''}<button type="button" class="button light" data-action="close-modal">Cancel</button><button type="submit" class="button">✧ Save challenge</button></div></form>`});
}
function masteryHasCycle(nodes){const map=new Map(nodes.map(n=>[n.id,n]));const visited=new Set(),stack=new Set();function visit(id){if(stack.has(id))return true;if(visited.has(id))return false;visited.add(id);stack.add(id);for(const dep of (map.get(id)?.requires||[])){if(map.has(dep)&&visit(dep))return true;}stack.delete(id);return false;}return nodes.some(n=>visit(n.id));}
function masteryDependents(nodes,id){const found=new Set([id]);let changed=true;while(changed){changed=false;for(const n of nodes){if(!found.has(n.id)&&(n.requires||[]).some(r=>found.has(r))){found.add(n.id);changed=true;}}}return [...found];}
function masteryDeleteNode(nodeId){
 const skill=state.skills.find(s=>s.id===selectedStarId)||state.skills[0];if(!skill)return;
 const {nodes,proofs}=masteryData(skill.id),node=nodes.find(n=>n.id===nodeId);if(!node)return;
 const dependencies=nodes.filter(n=>(n.requires||[]).includes(nodeId));if(dependencies.length){toast('Other sigils rely on this one. Edit their prerequisites before deleting it.');return;}
 if(!confirm(`Delete “${node.title}” and its recorded proof? Practice XP will remain.`))return;
 state.masteryTrees[skill.id]=nodes.filter(n=>n.id!==nodeId);delete proofs[nodeId];save();closeModal();render();toast('Sigil removed from the path.');
}
function masteryUndo(nodeId){
 const skill=state.skills.find(s=>s.id===selectedStarId)||state.skills[0];if(!skill)return;
 const {nodes,proofs}=masteryData(skill.id);if(!proofs[nodeId])return;
 const cascade=masteryDependents(nodes,nodeId).filter(id=>proofs[id]);
 if(!confirm(`Unclaim ${cascade.length} earned sigil${cascade.length===1?'':'s'}, including any unlocked descendants? Your practice sessions and XP will stay untouched.`))return;
 for(const id of cascade)delete proofs[id];save();closeModal();render();toast('Those sigils are unclaimed; your practice remains.');
}
function masteryReset(){
 const skill=state.skills.find(s=>s.id===selectedStarId)||state.skills[0];if(!skill)return;
 if(!confirm(`Restore the starter mastery tree for ${skill.name}? This removes custom challenges AND saved mastery proofs for this skill. Your XP and practice remain.`))return;
 state.masteryTrees[skill.id]=seedMasteryTree(skill);state.masteryProofs[skill.id]={};save();render();toast('Starter path restored.');
}
