document.addEventListener('change',e=>{
 const t=e.target;if(t.id!=='masterySkillPicker')return;
 if(!state.skills.some(s=>s.id===t.value))return;
 selectedStarId=t.value;render();document.getElementById('masteryAtlas')?.scrollIntoView({block:'start',behavior:'auto'});
});
document.addEventListener('submit',e=>{
 const id=e.target.getAttribute('id');if(!['masteryNodeForm','masteryProofForm'].includes(id))return;e.preventDefault();
 const f=new FormData(e.target),skillId=String(f.get('skillId')||'');if(!state.skills.some(s=>s.id===skillId)){toast('Select a valid skill.');return;}
 const {nodes,proofs}=masteryData(skillId);
 if(id==='masteryProofForm'){
  const nodeId=String(f.get('nodeId')||''),node=nodes.find(n=>n.id===nodeId),note=String(f.get('note')||'').trim().slice(0,1600),link=String(f.get('link')||'').trim().slice(0,1200);
  if(!node||masteryStatus(node,proofs)==='locked'){toast('This challenge is still sealed.');return;}
  if(note.length<10){toast('Write at least ten characters describing what you demonstrated.');return;}
  if(link&&!/^https?:\/\//i.test(link)){toast('Use a full http(s) URL for evidence.');return;}
  proofs[nodeId]={note,link,completedAt:proofs[nodeId]?.completedAt||localISO(new Date())};save();closeModal();render();document.getElementById('masteryAtlas')?.scrollIntoView({block:'start'});toast('✦ A new sigil is yours — real proof, not just XP.');return;
 }
 if(id==='masteryNodeForm'){
  const nodeId=String(f.get('id')||''),title=String(f.get('title')||'').trim().slice(0,90),challenge=String(f.get('challenge')||'').trim().slice(0,650),branch=String(f.get('branch')||''),glyph=String(f.get('glyph')||'✧').trim().slice(0,3)||'✧',requires=f.getAll('requires').map(String);
  if(!title||!challenge||!MASTERY_LANES.some(l=>l.key===branch)){toast('Give your sigil a name, goal and pathway.');return;}
  const target=nodes.find(n=>n.id===nodeId),idForNode=target?.id||uniqueId('mastery');
  const validRefs=requires.filter(r=>r!==idForNode&&nodes.some(n=>n.id===r));
  const candidate={id:idForNode,title,challenge,branch,glyph,requires:[...new Set(validRefs)]};
  const proposed=target?nodes.map(n=>n.id===idForNode?candidate:n):[...nodes,candidate];
  if(proofs[idForNode]&&!candidate.requires.every(r=>!!proofs[r])){toast('This sigil is already earned. Complete its new prerequisites or unclaim it first.');return;}
  if(masteryHasCycle(proposed)){toast('Those prerequisites create a loop. Choose a different dependency.');return;}
  state.masteryTrees[skillId]=proposed;save();closeModal();render();document.getElementById('masteryAtlas')?.scrollIntoView({block:'start'});toast('Your mastery path has been rewritten.');
 }
});
